<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Balloon Bow — Win95 Archery</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323&display=swap" rel="stylesheet">
<style>
  html, body { margin:0; padding:0; height:100%; overflow:hidden; background:#000; }
  #wrap { position:fixed; inset:0; display:flex; align-items:center; justify-content:center; }
  canvas { image-rendering:pixelated; cursor:crosshair; }
</style>
</head>
<body>
<div id="wrap"><canvas id="c"></canvas></div>
<script>
"use strict";
// ============ Win95 Balloon Archery ============
// Aim with mouse. Press & hold to draw the bow (power), release to fire.
// Pop balloons for points. Balloons that drift off the top = lost.
// Lose all 3 lives (a balloon escapes) and it's game over.

const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');

// Fixed internal resolution, scaled to fit window (keeps pixel look)
const W = 960, H = 540;
let scale = 1;
function resize() {
  const s = Math.min(window.innerWidth / W, window.innerHeight / H);
  scale = Math.max(0.2, s);
  canvas.width = Math.round(W * scale);
  canvas.height = Math.round(H * scale);
  canvas.style.width = canvas.width + 'px';
  canvas.style.height = canvas.height + 'px';
  ctx.setTransform(scale, 0, 0, scale, 0, 0);
}
window.addEventListener('resize', resize);
resize();

// ---------- Audio (WebAudio, no assets) ----------
let AC = null;
function audio() {
  if (!AC) {
    try { AC = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { AC = null; }
  }
  if (AC && AC.state === 'suspended') AC.resume();
  return AC;
}
function beep(freq, dur, type, vol, slideTo) {
  const ac = audio(); if (!ac) return;
  const t = ac.currentTime;
  const o = ac.createOscillator();
  const g = ac.createGain();
  o.type = type || 'square';
  o.frequency.setValueAtTime(freq, t);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(30, slideTo), t + dur);
  g.gain.setValueAtTime(vol || 0.15, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g); g.connect(ac.destination);
  o.start(t); o.stop(t + dur + 0.02);
}
function noiseBurst(dur, vol, filterFreq) {
  const ac = audio(); if (!ac) return;
  const t = ac.currentTime;
  const n = Math.floor(ac.sampleRate * dur);
  const buf = ac.createBuffer(1, n, ac.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);
  const src = ac.createBufferSource(); src.buffer = buf;
  const f = ac.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = filterFreq || 1200;
  const g = ac.createGain(); g.gain.setValueAtTime(vol || 0.3, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(f); f.connect(g); g.connect(ac.destination);
  src.start(t);
}
const sfx = {
  draw() { beep(180, 0.08, 'sawtooth', 0.05, 120); },
  shoot() { noiseBurst(0.12, 0.35, 2500); beep(700, 0.06, 'square', 0.12, 200); },
  pop(combo) {
    const base = 600 + Math.min(combo, 6) * 120;
    beep(base, 0.09, 'square', 0.22, base * 2.2);
    noiseBurst(0.06, 0.25, 4000);
  },
  lose() { beep(300, 0.5, 'sawtooth', 0.2, 60); },
  win() { [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => beep(f, 0.18, 'square', 0.18), i * 130)); },
  ui() { beep(440, 0.06, 'square', 0.1); },
};

// ---------- Game state ----------
const G = {
  state: 'title',      // title | play | over | win
  score: 0,
  lives: 3,
  target: 15,          // balloons to pop to win level 1
  popped: 0,
  combo: 0,
  comboTimer: 0,
  time: 0,
};
const archer = { x: 120, y: H - 90, aim: -Math.PI / 4, draw: 0, drawing: false };
let balloons = [];
let arrows = [];
let particles = [];
let floaters = [];     // floating score text
